// Run with an extracted @phosphor-icons/core@2.1.1 package directory.
// The generated files are committed; app builds need no download or generator.
import assert from 'node:assert/strict';
import { readFile, writeFile, readdir } from 'node:fs/promises';
import { resolve, join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { format } from 'prettier';
import { commonHabitIcons } from '../packages/core/src/commonHabitIcons.ts';

const directory = resolve(process.argv[2] ?? '.dev/phosphor/package');
const pkg = JSON.parse(await readFile(join(directory, 'package.json'), 'utf8'));
assert.equal(pkg.name, '@phosphor-icons/core');
assert.equal(pkg.version, '2.1.1');
const { icons } = await import(
  pathToFileURL(join(directory, 'dist/index.mjs'))
);
const overrides = new Map(commonHabitIcons.map((icon) => [icon.id, icon]));
const catalog = [];
const paths = {};
for (const icon of [...icons].sort((a, b) =>
  a.name.localeCompare(b.name, 'en'),
)) {
  const svg = await readFile(
    join(directory, 'assets/regular', `${icon.name}.svg`),
    'utf8',
  );
  // Fail rather than silently drop new SVG shapes or rendering attributes.
  const match = svg
    .trim()
    .match(
      /^<svg\b[^>]*>(<path d="([^"]+)"\s*\/>|<path d="([^"]+)"><\/path>)<\/svg>$/,
    );
  assert.ok(match, `Unexpected SVG structure: ${icon.name}`);
  paths[icon.name] = [match[2] ?? match[3]];
  const common = overrides.get(icon.name);
  catalog.push({
    id: icon.name,
    label:
      common?.label ??
      icon.name
        .split('-')
        .map((word) => word[0].toUpperCase() + word.slice(1))
        .join(' '),
    tags: [
      ...new Set([
        ...(icon.tags ?? []),
        ...(icon.categories ?? []),
        icon.alias?.name ?? '',
        common?.tags ?? '',
      ]),
    ]
      .filter(Boolean)
      .join(' '),
  });
}
assert.equal(catalog.length, 1512);
assert.equal(
  (await readdir(join(directory, 'assets/regular'))).filter((name) =>
    name.endsWith('.svg'),
  ).length,
  catalog.length,
);
for (const id of overrides.keys())
  assert.ok(paths[id], `Missing saved ID: ${id}`);
const header =
  '// Generated by scripts/generate-phosphor.mjs from @phosphor-icons/core 2.1.1.\n// MIT: docs/licenses/PHOSPHOR_LICENSE.txt. Retain stable IDs for saved habits.\n';
for (const [name, source] of [
  [
    'habitIconCatalog.ts',
    `export const habitIconCatalog = ${JSON.stringify(catalog)} as const;\n`,
  ],
  [
    'phosphorPaths.ts',
    `export const phosphorPaths: Record<string, string[]> = ${JSON.stringify(paths)};\n`,
  ],
]) {
  await writeFile(
    new URL(`../packages/core/src/${name}`, import.meta.url),
    await format(header + source, { parser: 'typescript', singleQuote: true }),
  );
}
console.log(
  `Generated ${catalog.length} regular icons and searchable metadata.`,
);
